<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');
if ($_SERVER['REQUEST_METHOD'] !== 'POST') { http_response_code(405); exit(json_encode(['ok'=>false])); }
$storage = getenv('JTM_VISA_STORAGE');
if (!$storage) { http_response_code(503); exit(json_encode(['ok'=>false,'message'=>'Visa service is not configured.'])); }
$type = $_POST['visaType'] ?? ''; $speed = $_POST['processingSpeed'] ?? 'normal'; $quantity = max(1,min(10,(int)($_POST['quantity'] ?? 1)));
$prices=['transit-48'=>500000,'transit-96'=>1500000,'tourist-30-single'=>3625000,'tourist-60-single'=>5880000,'tourist-30-multiple'=>7000000,'tourist-60-multiple'=>11400000];
if (!isset($prices[$type]) || !filter_var($_POST['email'] ?? '', FILTER_VALIDATE_EMAIL)) { http_response_code(422); exit(json_encode(['ok'=>false,'message'=>'Please complete the required details.'])); }
$surcharge=$speed==='express'?500000:($speed==='super-express'?1200000:0); $total=($prices[$type]+$surcharge)*$quantity; $case='JTMV'.time();
$dir=rtrim($storage,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR.$case; if (!is_dir($dir) && !mkdir($dir,0700,true)) { http_response_code(500); exit(json_encode(['ok'=>false,'message'=>'Unable to prepare secure storage.'])); }
$allowed=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png']; $files=[];
foreach ($_FILES as $file) { if (($file['error'] ?? UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE) continue; if ($file['error']!==UPLOAD_ERR_OK || $file['size']>5*1024*1024) { http_response_code(422); exit(json_encode(['ok'=>false,'message'=>'Each document must be under 5 MB.'])); } $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']); if (!isset($allowed[$mime])) { http_response_code(422); exit(json_encode(['ok'=>false,'message'=>'Only PDF, JPG, and PNG documents are accepted.'])); } $name=bin2hex(random_bytes(8)).'.'.$allowed[$mime]; move_uploaded_file($file['tmp_name'],$dir.DIRECTORY_SEPARATOR.$name); $files[]=$name; }
$record=['caseNumber'=>$case,'status'=>'SUBMITTED','country'=>'AE','visaType'=>$type,'processingSpeed'=>$speed,'quantity'=>$quantity,'totalIDR'=>$total,'name'=>trim($_POST['fullName'] ?? ''),'email'=>$_POST['email'],'phone'=>trim($_POST['phone'] ?? ''),'nationality'=>trim($_POST['nationality'] ?? ''),'documents'=>$files,'createdAt'=>gmdate('c')]; file_put_contents($dir.DIRECTORY_SEPARATOR.'application.json',json_encode($record,JSON_PRETTY_PRINT),LOCK_EX);
$subject="Jasa Tiket Murah — UAE Visa application $case"; $body="<h2>Application received</h2><p>Your UAE visa application reference is <b>$case</b>.</p><p>Status: <b>SUBMITTED</b><br>Total: <b>Rp".number_format($total,0,',','.')."</b></p>"; $headers="MIME-Version: 1.0\r\nContent-Type: text/html; charset=UTF-8\r\nFrom: noreply@jasatiketmurah.com\r\nCc: cs@jasatiketmurah.com\r\nBcc: jasatiketmurah@gmail.com"; @mail($record['email'],$subject,$body,$headers);
$paymentUrl=null; $key=getenv('XENDIT_SECRET_KEY'); if ($key && function_exists('curl_init')) { $payload=json_encode(['external_id'=>$case,'amount'=>$total,'payer_email'=>$record['email'],'description'=>'UAE Visa '.$case]); $ch=curl_init('https://api.xendit.co/v2/invoices'); curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$payload,CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_USERPWD=>$key.':',CURLOPT_RETURNTRANSFER=>true]); $response=json_decode((string)curl_exec($ch),true); curl_close($ch); $paymentUrl=$response['invoice_url']??$response['payment_link_url']??null; }
echo json_encode(['ok'=>true,'caseNumber'=>$case,'paymentUrl'=>$paymentUrl]);
